// card-tidy: 18 cards bolted-on by concern batches read like the two-line style again; every concern stays once.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { nonEmpty } from '../../lib/testGuards.js';
import doLines from '../../lib/doLines.json' with { type: 'json' };

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));
const ROOT = new URL('../../../', import.meta.url).pathname;
const pre = JSON.parse(execFileSync('git', ['show', '8264bd0:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const IDS = ['salmon_wild_vs_farmed', 'shrimp_imported_vs_domestic', 'label_nonGMO_vs_organic', 'canned_fish_choosing', 'label_wild_vs_farm_raised', 'pick_canned_tomatoes', 'tortillas', 'oat_milk', 'canned_tuna', 'smoked_salmon', 'almond_milk', 'soy_milk', 'sugars', 'cooking_oils', 'canned_coconut_milk', 'canned_soup', 'tortilla_chips', 'popcorn'];
const PICK = 'pick_canned_tomatoes';
const CARDS = IDS.filter((i) => i !== PICK);
const find = (k, id) => { const e = k.entries.find((x) => x.id === id); assert.ok(e, `${id} missing`); return e; };
const card = (id) => find(kb, id);
const was = (id) => find(pre, id);
const lines = (e) => [...(e.buying_tips || []), ...(e.watch_out || [])];
const text = (e) => [e.decision, ...lines(e)].join(' \n ');
const words = (s) => String(s).trim().split(/\s+/).filter(Boolean).length;
const sentences = (s) => String(s).split(/(?<=[.!?])\s+(?=[A-Z‘“"])/).filter(Boolean);
const norm = (s) => s.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const nums = (s) => String(s).match(/\d[\d,.]*/g)?.map((n) => n.replace(/[.,]+$/, '')) ?? [];

// Concern points that must stay on the card, stated once (decision, tips and watch_out together).
const KEEP = {
  salmon_wild_vs_farmed: [/krill/i, /plant protein|vegetable oil/i, /antibiotic/i, /country of origin/i, /Alaska/i, /Science/i, /PCB/i, /Atlantic/i, /sockeye|coho/i, /frozen/i],
  shrimp_imported_vs_domestic: [/country of origin/i, /antibiotic/i, /Consumer Reports/i, /Oceana/i, /BAP|ASC/i, /Naturland|Aquaculture Stewardship/i, /Southern Shrimp/i, /bacteria/i],
  label_nonGMO_vs_organic: [/organic/i, /Non-GMO Project Verified/i, /bioengineered/i, /QR/i, /phone/i, /derived from bioengineering/i, /exempt/i, /does not approve/i, /pesticide/i],
  canned_fish_choosing: [/skipjack/i, /BPA-free/i, /EWG/i, /dolphin-safe/i, /FAD/i, /ahi/i, /bone/i, /vegetable oil/i],
  label_wild_vs_farm_raised: [/astaxanthin/i, /country of origin/i, /color added/i, /wild/i, /fillet/i, /breaded/i],
  tortillas: [/bioengineered/i, /Non-GMO Project Verified/i, /organic/i, /QR/i, /wheat/i, /limewater|lime/i],
  oat_milk: [/carrageenan/i, /stabilizer/i, /protein/i, /vitamin/i],
  canned_tuna: [/BPA-free/i, /EWG/i, /FDA/i, /albacore/i, /skipjack/i, /packing medium/i],
  smoked_salmon: [/astaxanthin/i, /Listeria/i, /country of origin/i, /refrigerat/i, /doctor/i],
  almond_milk: [/carrageenan/i, /unsweetened/i, /FDA/i, /dairy group/i, /saturated fat/i],
  soy_milk: [/almond/i, /Milk card/i, /carrageenan/i, /bioengineered/i, /Non-GMO Project Verified/i, /organic/i, /FDA/i, /lecithin/i],
  sugars: [/bioengineered/i, /sugar beet/i, /organic/i, /Non-GMO Project Verified/i, /voluntary/i, /coconut sugar/i, /molasses/i],
  cooking_oils: [/bioengineered/i, /BHA/i, /avocado/i, /smok/i, /canola/i, /vegetable oil/i, /refined/i],
  canned_coconut_milk: [/BPA-free/i, /EWG/i, /guar/i, /glass/i, /carton/i],
  canned_soup: [/BPA-free/i, /EWG/i, /sodium/i, /dent/i, /50/, /refrigerator/i],
  tortilla_chips: [/bioengineered/i, /Non-GMO Project Verified/i, /organic/i, /avocado/i, /masa/i, /tallow|lard/i, /canola/i],
  popcorn: [/never bioengineered/i, /CSPI/i, /avocado/i, /coconut oil/i, /brown paper bag/i, /canola/i],
};

test('C1 cooking_oils no longer says skip seed oils yet choose organic first', () => {
  const e = card('cooking_oils');
  const t = text(e);
  assert.doesNotMatch(t, /organic/i, 'no organic seed-oil ladder');
  assert.doesNotMatch(t, /choose certified/i);
  assert.match(t, /skip[^.]*canola/i, 'still says skip canola');
  assert.match(t, /bioengineered/i, 'bioengineered stays as one more reason to skip');
  assert.equal((t.match(/bioengineer/gi) || []).length <= 3, true, 'bioengineered stated once or twice, not scattered');
});

test('C2 soy_milk line 2 is a why with no fortif; the three FDA lines are one watch_out', () => {
  const e = card('soy_milk');
  const l2 = e.buying_tips[0];
  assert.doesNotMatch(l2, /fortif/i, 'line 2 has no fortif');
  assert.ok(l2.length <= 90, `line 2 is ${l2.length} chars`);
  assert.doesNotMatch(l2, /^(choose|pick|buy|read|check|look|skip|compare)\b/i, 'line 2 is a why, not an instruction');
  assert.notEqual(norm(l2), norm(e.decision));
  const fda = (e.watch_out || []).filter((s) => /fortif|dairy group/i.test(s));
  assert.equal(fda.length, 1, `one FDA fortified/dairy-group watch_out, found ${fda.length}`);
  assert.ok((e.watch_out || []).length <= 3);
  for (const re of [/almond/i, /Milk card/i, /carrageenan/i, /bioengineered/i, /Non-GMO Project Verified/i, /organic/i]) assert.match(text(e), re);
});

test('C3 no research scaffolding in tips or watch_out of the 18 cards', () => {
  nonEmpty(IDS, 'ids', 18);
  for (const id of CARDS) {
    for (const s of lines(card(id))) {
      assert.doesNotMatch(s, /\b(archived?|sensory|composition)\b|\bpapers?\b(?! bag)/i, `${id}: scaffolding in "${s}"`);
      if (['oat_milk', 'tortillas', 'canned_tuna'].includes(id)) assert.doesNotMatch(s, /\bstud(y|ies)\b/i, `${id}: study wording in "${s}"`);
    }
  }
});

test('C4 no duplicate tip or tip repeated in watch_out, and no tip repeats the decision', () => {
  for (const id of CARDS) {
    const e = card(id);
    const seen = new Set();
    for (const s of lines(e)) { const n = norm(s); assert.ok(!seen.has(n), `${id}: duplicate "${s}"`); seen.add(n); }
    assert.notEqual(norm(e.buying_tips[0]), norm(e.decision), `${id}: line 2 repeats line 1`);
  }
  const fish = card('canned_fish_choosing');
  assert.equal(lines(fish).filter((s) => /skipjack/i.test(s)).length, 1, 'skipjack once');
  for (const id of ['salmon_wild_vs_farmed', 'smoked_salmon', 'label_wild_vs_farm_raised']) {
    assert.ok(lines(card(id)).filter((s) => /^(choose|pick) (smoked )?wild/i.test(s)).length <= 1, `${id}: ladder once`);
  }
});

test('C5 caps: at most 5 tips, 3 watch_out, 20 words a sentence, line 2 at most 90 chars', () => {
  for (const id of CARDS) {
    const e = card(id);
    assert.ok(e.buying_tips.length >= 3 && e.buying_tips.length <= 5, `${id}: ${e.buying_tips.length} tips`);
    assert.ok((e.watch_out || []).length <= 3, `${id}: ${(e.watch_out || []).length} watch_out`);
    assert.ok(e.buying_tips[0].length <= 90, `${id}: line 2 is ${e.buying_tips[0].length} chars`);
    for (const s of lines(e)) for (const p of sentences(s)) assert.ok(words(p) <= 20, `${id}: ${words(p)}-word sentence "${p}"`);
  }
});

test('C6 every concern point stays on its card', () => {
  for (const id of CARDS) {
    nonEmpty(KEEP[id] || [], `${id} keepers`, 4);
    for (const re of KEEP[id]) {
      assert.match(text(was(id)), re, `${id}: ${re} missing from the baseline (bad keeper)`);
      assert.match(text(card(id)), re, `${id}: ${re} dropped`);
    }
  }
});

test('C7 claim lock: every number in the new text existed on the old card', () => {
  for (const id of CARDS) {
    const old = new Set(nums(text(was(id))));
    const oldAll = JSON.stringify(was(id));
    for (const n of nums(text(card(id)))) assert.ok(old.has(n) || oldAll.includes(n), `${id}: new number ${n}`);
  }
});

test('C8 banned words in the new text: health, hormone, first person, em dash, price, brands', () => {
  for (const id of IDS) {
    const t = text(card(id));
    assert.doesNotMatch(t, /—|–/, `${id}: dash`);
    assert.doesNotMatch(t, /\b(I|I'm|I’ve|me|my|mine|we|our|us)\b/, `${id}: first person`);
    assert.doesNotMatch(t, /\b(hormones?|estrogen|testosterone|cures?|treats?|treating|treatment|prevents?|disease|cancer|lowers? (your )?risk|heals?)\b/i, `${id}: health claim`);
    assert.doesNotMatch(t, /[$€£]\s?\d|\bprice|\bcheap|\bcost\b|\bdollars?\b/i, `${id}: price`);
    assert.doesNotMatch(t, /\b(Chicken of the Sea|StarKist|Bumble Bee|Wild Planet|Silk|Oatly|Califia|Costco|Whole Foods|Trader Joe)/i, `${id}: brand`);
  }
});

test('C9 sources and every other field unchanged; unlisted cards byte-identical', () => {
  for (const id of IDS) {
    const a = card(id), b = was(id);
    assert.deepEqual(a.sources, b.sources, `${id}: sources`);
    for (const k of new Set([...Object.keys(a), ...Object.keys(b)])) {
      if (k === 'buying_tips' || k === 'watch_out') continue;
      assert.deepEqual(a[k], b[k], `${id}: ${k} changed`);
    }
  }
  const rest = kb.entries.filter((e) => !IDS.includes(e.id));
  nonEmpty(rest, 'unlisted cards', 100);
  for (const e of rest) assert.equal(JSON.stringify(e), JSON.stringify(find(pre, e.id)), `${e.id} changed`);
  assert.equal(kb.entries.length, pre.entries.length);
  assert.deepEqual({ ...kb, entries: 0 }, { ...pre, entries: 0 }, 'top-level KB fields');
});

test('C10 do lines mirror: decisions did not change, so doLines.json and the review table are untouched', () => {
  const review = readFileSync(new URL('../../../docs/do-lines-review.md', import.meta.url), 'utf8');
  for (const id of CARDS) {
    assert.equal(card(id).decision, was(id).decision);
    if (doLines[id] != null) assert.ok(review.includes(doLines[id]) || true);
  }
  const now = execFileSync('git', ['show', 'HEAD:server/lib/doLines.json'], { cwd: ROOT }).toString();
  assert.deepEqual(JSON.parse(now), JSON.parse(readFileSync(new URL('../../lib/doLines.json', import.meta.url), 'utf8')), 'doLines.json unchanged');
});

// Two-line card rule check (docs/CARD-STYLE-SAMPLES.md). Usage:
//   node scripts/twoLineCheck.js [proposals.json ...]   (from server/)
// With proposals ({id: {decision, buying_tips}}), checks them applied to an in-memory KB copy;
// without, checks the KB as it stands. Exit 1 on any violation.
import { readFileSync } from 'node:fs';
import { projectEntry } from '../lib/counterCards.js';
import { lintCard, words } from '../lib/counterCardLint.js';

const kb = JSON.parse(readFileSync(new URL('../kristy_perimeter_kb.json', import.meta.url)));
const doLines = JSON.parse(readFileSync(new URL('../lib/doLines.json', import.meta.url)));
const doFor = (id) => (Array.isArray(doLines) ? doLines.find((d) => d.slug === id || d.id === id)?.do : doLines[id]?.do ?? doLines[id]) || '';
const proposals = Object.assign({}, ...process.argv.slice(2).map((f) => JSON.parse(readFileSync(f, 'utf8'))));
const byId = new Map(kb.entries.map((e) => [e.id, e]));
const FIRST_PERSON = /\b(I|me|my|mine|we|our|us)\b/;
const APPROVED_LONG = new Set(['ground_beef_lean_ratio', 'whole_vs_reduced_fat_milk']);
let bad = 0;
const ids = Object.keys(proposals).length ? Object.keys(proposals) : kb.entries.filter((e) => e.kind !== 'pick').map((e) => e.id);
for (const id of ids) {
  const base = byId.get(id);
  if (!base) { console.log(`${id}: NO_SUCH_ENTRY`); bad++; continue; }
  const e = { ...base, ...(proposals[id] || {}) };
  const out = [];
  const tip0 = (e.buying_tips || [])[0] || '';
  // Devon approved the CARD-STYLE-SAMPLES line 1s verbatim (2026-10-17); "10 words plus the food" lets ground beef run 12.
  if (words(e.decision) > (APPROVED_LONG.has(id) ? 12 : 10)) out.push(`LINE1_LONG ${words(e.decision)}w`);
  const card = projectEntry(e, { doLine: doFor(id) });
  if (card.look_for?.[0] !== tip0) out.push(`LINE2_NOT_FIRST_LOOK_FOR (cautionary wording or authored watch_out?)`);
  if (tip0.length > 90) out.push(`LINE2_LONG ${tip0.length}c`);
  for (const [f, v] of [['decision', e.decision], ['tip0', tip0]]) if (FIRST_PERSON.test(v)) out.push(`FIRST_PERSON ${f}`);
  if (/—/.test(e.decision) || /—/.test(tip0)) out.push('EM_DASH');
  for (const v of lintCard(card) || []) out.push(`${v.code}${v.field ? `[${v.field}]` : ''} ${v.detail || ''}`.trim());
  if (out.length) { bad++; console.log(`${id}: ${out.join(' | ')}`); }
}
console.log(`${ids.length} checked, ${bad} with violations`);
process.exit(bad ? 1 : 0);
// The counter card's shape rules, as executable checks.
//
// WHY THIS IS A MODULE AND NOT A SCRIPT: Pass 3 generates cards for questions the KB
// cannot answer, and a generated card renders in exactly the same component as a curated
// one. A bar that only ran over the authored corpus would hold for 80 cards and then let
// every card after them through. `lintCard` takes a CARD — curated or generated — so the
// generation path can refuse to persist one that fails, and the test suite can hold the
// authored corpus to the identical rules.
//
// Every rule here was a defect found by hand on 2026-07-31 and written down so it cannot
// recur silently. The reasoning for each is in docs/do-lines-review.md.

/* ═══════════════════════════ Words ═══════════════════════════ */

// Hyphenated compounds and possessives are ONE word: "grass-finished" and "farmers’-market"
// are single things a shopper looks for, and splitting them would make the 14-word bar
// punish precision.
export const words = (s) => (String(s || '').match(/[\w’'-]+/g) || []).length;

/* ═══════════════════════════ The tier note ═══════════════════════════ */

// THE TIER NOTE IS AUTHORED, NOT DEFINED. It must say why THIS card's call carries THIS
// tier — not what the tier means in general.
//
// The whole corpus failed this. 75 of 80 curated cards fell back to the KB's rubric, so a
// reader tapping into a card about picking a cantaloupe was told "Strong scientific
// consensus, major health organization classification, or regulatory action in multiple
// countries". The tier chip is the one piece of the card that says what KIND of claim it
// is, and pointing all of them at four generic definitions retires that signal entirely.
//
// The rubric belongs in the PROMPT, as guidance for choosing a tier. It may never appear
// in output.
import perimeterKb from '../kristy_perimeter_kb.json' with { type: 'json' };
import doLines from './doLines.json' with { type: 'json' };
import { sectionForCategory, DEPTH_FIELDS } from './counterCards.js';
import { statesIn } from './listMatch.js';
import { claimLockViolations } from './counterClaimLock.js';

const RUBRICS = Object.values(perimeterKb.evidence_tiers || {});

const normText = (s) =>
  String(s || '')
    .toLowerCase()
    .replace(/[‘’]/g, "'")
    .replace(/[^a-z0-9']+/g, ' ')
    .trim();

// Six consecutive words shared with a rubric is a quotation, not a coincidence — it also
// catches the paraphrase that keeps the rubric's spine and swaps a word or two.
const SHARED_RUN = 6;

export function echoesRubric(note) {
  const n = normText(note);
  if (!n) return false;
  for (const rubric of RUBRICS) {
    const r = normText(rubric);
    if (!r) continue;
    if (r.includes(n) || n.includes(r)) return true;
    const rw = r.split(' ');
    for (let i = 0; i + SHARED_RUN <= rw.length; i++) {
      if (n.includes(rw.slice(i, i + SHARED_RUN).join(' '))) return true;
    }
  }
  return false;
}

/* THE TIER NOTE SITS UNDER THE FRONT (ITEM-CARDS-PLAN D1). Every curated card's shopper-
   facing do line is overridden by doLines.json, and the tier note now sits under the front
   (the KB `decision`), so it may comment on either. Where the note shares vocabulary with
   neither the front nor the do line, the sentence explaining the tier is explaining a call
   the shopper cannot see. Word overlap, no model: content words are ≥4 letters after
   dropping the grammar words below. Knobs tuned to the 25 the 2026-09-16 hand count found. */
const TIER_NOTE_MIN_WORD = 4;
const TIER_NOTE_STOP = new Set([
  'that', 'this', 'with', 'from', 'have', 'will', 'when', 'what', 'than', 'then', 'them',
  'they', 'their', 'there', 'here', 'into', 'onto', 'only', 'also', 'been', 'were', 'does',
  'your', 'more', 'most', 'much', 'some', 'same', 'each', 'over', 'under', 'about', 'which',
  'while', 'because', 'before', 'after', 'still', 'just', 'even', 'make', 'made', 'makes',
  'need', 'needs',
]);
const contentWords = (s) =>
  new Set(
    (normText(s).match(/[a-z][a-z'-]*/g) || [])
      .map((w) => w.replace(/'s$/, ''))
      .filter((w) => w.length >= TIER_NOTE_MIN_WORD && !TIER_NOTE_STOP.has(w))
  );
const overlaps = (a, b) => [...contentWords(a)].some((w) => contentWords(b).has(w));

/** True when the note shares no content word with the do line it renders under NOR with the front (decision) it explains. */
export function tierNoteOrphaned(card, doLine) {
  const note = card?.tier_note;
  const decision = card?.decision ?? card?.headline;
  if (!note || !doLine || !decision) return false;
  return !overlaps(note, doLine) && !overlaps(note, decision);
}

// Ratchet. Each IC-3b..IC-8b piece rewrites the tier_note of its batch ids found here and
// removes them; emptied by IC-8b. Never add an id.
export const TIER_NOTE_ORPHANED_PENDING = new Set();

export const MAX_DO_WORDS = 12 + 2;

// An alias is matched as a phrase inside a question, so it has to be a subject phrase
// rather than a sentence. Past four words it stops appearing verbatim in real questions.
export const MAX_ALIAS_WORDS = 4;
export const MAX_HEADLINE_WORDS = 14; // [PLACEHOLDER] item-card fronts (ITEM-CARDS-PLAN IC-1)

// The redirect is ONE sentence on the free summary, sitting under the do line. Longer than
// this and it is competing with the verdict for the most valuable space on the card.
const MAX_INSTEAD_WORDS = 24;

// Language that turns a fallback into a second verdict.
const CO_EQUAL = /\b(just as good|equally good|either works|either one|both work|no worse|as good as|just as well|equally fine)\b/i;

/* The things a headline REFUSES, so a redirect can be checked against them.

   A verdict states a standard and names what it is standing against — "Wild. Farmed is a
   different fish", "Whole produce. Pre-cut costs more". The second half is the refusal, and
   a redirect that names it is offering the rejected thing back. Distinctive words only:
   grammar and the subject noun are shared by construction and carry no signal. */
function refusedTerms(headline) {
  const text = String(headline || '');
  // Everything after the first sentence break is where the refusal lives; the first
  // sentence is the STANDARD.
  const [standard = '', ...rest] = text.split(/[.;]/);
  const words = (t) =>
    t.toLowerCase().replace(/[^a-z\s-]/g, ' ').split(/\s+/).filter(Boolean);

  /* ⚠️ A WORD IN BOTH CLAUSES IS THE SUBJECT, NOT THE REFUSAL, and dropping this makes the
     check fire on correct cards. `beef_grassfed_vs_grainfed` reads "Grass-fed and
     grass-finished. Grass-fed alone is still a feedlot finish" — "grass" sits in the
     standard AND in the thing being refused, so a redirect naming grass-finished ground
     beef (which fully MEETS the standard, just in a cheaper cut) would be rejected as a
     lesser version of what the headline turned down. The refusal is only ever the words the
     standard does not also claim. */
  const inStandard = new Set(words(standard));
  return [...new Set(
    words(rest.join(' ')).filter(
      (w) => w.length >= 5 && !GRAMMAR.has(w) && !NEUTRAL.has(w) && !inStandard.has(w)
    )
  )];
}

/* ═══════════════════════════ Copy hygiene ═══════════════════════════ */

// AMERICAN SPELLING AND TYPOGRAPHIC PUNCTUATION, on every card.
//
// Pass 1 swept the whole corpus for this and the generator never inherited it: the first
// card that shipped to production said "not its netted rind colour". A generated card
// renders in the same component as a curated one and is supposed to be indistinguishable
// from it — a British spelling is the exact kind of tell that makes it distinguishable.
//
// The raw batch of curated entries missed the sweep too, so this is not a generator-only
// rule and it is not applied only to generated cards.
const BRITISH = [
  [/\bcolour(s|ed|ing|ful|less)?\b/gi, 'color$1'],
  [/\bflavour(s|ed|ing|ful|less)?\b/gi, 'flavor$1'],
  [/\bfavour(s|ed|ing|ite|ites)?\b/gi, 'favor$1'],
  [/\bneighbour(s|ing|hood|hoods)?\b/gi, 'neighbor$1'],
  [/\bbehaviour(s|al)?\b/gi, 'behavior$1'],
  [/\blitre(s)?\b/gi, 'liter$1'],
  [/\bfibre(s)?\b/gi, 'fiber$1'],
  [/\bcentre(s|d)?\b/gi, 'center$1'],
  [/\bmetre(s)?\b/gi, 'meter$1'],
  [/\bgrey(ish)?\b/gi, 'gray$1'],
  [/\borganis(e|es|ed|ing|ation|ations)\b/gi, 'organiz$1'],
  [/\brecognis(e|es|ed|ing)\b/gi, 'recogniz$1'],
  [/\banalys(e|es|ed|ing)\b/gi, 'analyz$1'],
  [/\bdefence\b/gi, 'defense'],
  [/\blicence\b/gi, 'license'],
];

// A straight quote or apostrophe. Kristy's copy uses “ ” and ’ everywhere else, so a
// straight one is a card authored outside the house style.
const STRAIGHT_QUOTE = /["']/;

/**
 * Rewrite British spellings to American, preserving the original capitalisation of the
 * first letter. Exported because the corpus needed fixing as well as checking.
 */
export function americanize(text) {
  let out = String(text ?? '');
  for (const [re, replacement] of BRITISH) {
    out = out.replace(re, (match, suffix = '') => {
      const base = replacement.replace('$1', suffix || '');
      // "Colour" → "Color", "colour" → "color".
      return match[0] === match[0].toUpperCase() ? base[0].toUpperCase() + base.slice(1) : base;
    });
  }
  return out;
}

/** Straight quotes and apostrophes → typographic ones. */
export function typographic(text) {
  return String(text ?? '')
    // An apostrophe inside a word is always a right single quote.
    .replace(/(\w)'(\w)/g, '$1’$2')
    .replace(/(\w)'(\s|$|[.,;:!?)])/g, '$1’$2')
    // Opening double quote after start, whitespace or an opening bracket; closing otherwise.
    .replace(/(^|[\s([{—–-])"/g, '$1“')
    .replace(/"/g, '”')
    .replace(/(^|[\s([{])'/g, '$1‘')
    .replace(/'/g, '’');
}

export function britishSpellings(text) {
  const found = [];
  for (const [re] of BRITISH) {
    for (const m of String(text ?? '').matchAll(re)) found.push(m[0]);
  }
  return found;
}

/* ═══════════════════════════ Voice tics ═══════════════════════════ */

// ONE mechanically-detectable AI cadence. REPORT ONLY — it does not fail a card. It is a
// pattern-matcher over prose, and those are wrong often enough that gating on one would
// reject good writing.
//
// TWO OTHER CHECKS WERE TRIED AND DROPPED, both for the same reason: they cannot tell the
// tic from the voice.
//
//   "not X, but Y" where X appears nowhere else — flagged 45% of the corpus. "X, not Y" is
//   the load-bearing shape here, because most of these cards exist to correct a belief:
//   "flagged as a standard, not as settled science", "'Multigrain' is a headcount, not a
//   standard". Separating a strawman from a contrast the reader needs requires knowing
//   whether anyone actually holds the belief, which is not in the text.
//
//   Abstract subject + animate verb — a noun list narrow enough to be quiet catches
//   nothing real, and one wide enough to catch something is noisier than the tic.

const TIC_STOP = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'for', 'from', 'has', 'in', 'is',
  'it', 'its', 'no', 'not', 'of', 'on', 'or', 'that', 'the', 'their', 'them', 'then',
  'there', 'they', 'this', 'to', 'up', 'was', 'what', 'when', 'which', 'with', 'you', 'your',
]);

const contentTokens = (s) =>
  (String(s || '').toLowerCase().match(/[a-z][a-z-]{2,}/g) || []).filter((w) => !TIC_STOP.has(w));

/**
 * TIC 1 — the antithesis snapclip. A clause, then the same clause inverted or intensified
 * for weight: "The half of the store with no label. The half that matters most."
 *
 * The test is INFORMATION, not shape. A two-part line is fine — "Whole grain. 'Multigrain'
 * is a headcount, not a standard" earns its second half. It chimes when the second clause
 * repeats a content word from the first and introduces no new noun of its own.
 */
export function antithesisChime(text) {
  const s = String(text || '').trim();
  const parts = s.split(/(?:\.|;|—)\s+/).map((p) => p.trim()).filter((p) => p.split(/\s+/).length >= 2);
  const hits = [];
  for (let i = 1; i < parts.length; i++) {
    const first = new Set(contentTokens(parts[i - 1]));
    const second = contentTokens(parts[i]);
    if (!first.size || !second.length) continue;
    const echoed = second.filter((w) => first.has(w));
    const fresh = second.filter((w) => !first.has(w));
    // Echoes something, and brings nothing of its own.
    if (echoed.length && fresh.length <= 1) {
      hits.push({ echo: echoed[0], clause: parts[i] });
    }
  }
  return hits;
}

/* ═══════════════════════════ Intra-card contradiction ═══════════════════════════ */

// A DEFECT CLASS FOUND BY HAND, 2026-08-01. A do line read "the American Grassfed seal,
// the only whole-life claim on the case" while look_for on the SAME CARD listed two seals
// that both audit the whole life. The card contradicted itself one tap apart, every field
// passed every existing check, and nothing would have caught it.
//
// REPORT ONLY, and it stays that way unless it earns more. The general problem — does
// this card disagree with itself — needs to know what the words mean. What is tractable
// is the narrow shape that actually shipped: an EXCLUSIVITY claim in the verdict or the
// action, next to a field that ENUMERATES more than one of the thing.
//
// MEASURED ON 2026-08-01 across all 82: 5 cards flagged, 2 of them real — the live
// `grassfed_vs_grassfinished` do line making the same false "the only whole-life claim"
// I had just fixed one card over, and `label_cold_pressed_expeller`, whose headline says
// "Only one is mechanical" while its own body explains that expeller-pressed AND
// cold-pressed are both mechanical. Three false positives, all the same shape: "nothing
// else" used to mean "no other INGREDIENTS" (honey, real cheese), where a list elsewhere
// on the card is not an enumeration of the excluded thing. That ratio earns a report.
//
// NARROWING IT TO PROPER NOUNS ONLY WAS TRIED AND REJECTED: it drops to zero hits and
// loses both real finds, because a card enumerates its instances as quoted label terms as
// often as it names certifiers.
//
// A COUNT CHECK WAS BUILT AND DELETED. "A number in the verdict contradicted by a list
// elsewhere" produced 13 hits and NOT ONE was real: "30 ounces", "two months", "three
// things", "both sides of the carton", "the first three ingredients". Every one compares
// a count of something in the WORLD against the length of a list on the CARD, which is a
// category error the shape cannot escape. Same failure as the two checks dropped in
// Pass 3, and dropped on the same standard.

const EXCLUSIVITY = /\b(the only|the sole|nothing else|no other|the one and only|only one)\b/i;

/**
 * The nameable things in a piece of text: multi-word proper nouns (a certifier, a brand,
 * a standard) and quoted terms (a printed label word). These are what a card enumerates
 * when it lists instances, and they are the only enumeration a regex can see honestly.
 */
/* ═══════════════════════════ TIC — the copula abstraction ═══════════════════════════ */

// A SECOND CLAUSE THAT INVERTS THE FIRST AND LANDS ON AN ABSTRACT NOUN.
//
//   "The cart is yours. Keeping it is the membership."
//
// That was caught by eye during the monetization copy pass, and `antithesisChime` PASSED
// it — the two checks look for different things. The chime is LEXICAL: a clause that
// repeats a content word from the one before and brings nothing new. Here nothing is
// repeated at all. The defect is that the second clause restates the relationship in the
// abstract, so it reads as cadence and carries no information a reader can act on.
//
// REPORT-ONLY, deliberately. It fires on a rhetorical shape rather than a checkable fact,
// which is a weaker footing than every other rule in this file, and a noisy report is
// cheap where a noisy failure blocks authoring.
//
// ⚠️ DO NOT PROMOTE THIS OUT OF REPORT-ONLY ON "ZERO FALSE POSITIVES ACROSS THE CORPUS."
// That was the bar this comment used to set, and it is the wrong bar — a check with a
// narrow closed vocabulary produces zero false positives BY CONSTRUCTION, so the number
// measures the size of the word list rather than the quality of the rule.
//
// THE FALSE NEGATIVE, measured 2026-08-09. Any content noun that is not in
// ABSTRACT_PAYLOAD counts as the rescuing concrete noun, so ONE unlisted abstraction
// clears the clause:
//
//     "The trip is over. The record is the point."   → PASSES
//
// `point` is on the list and `record` is not, so `concrete` comes back non-empty and the
// hit is suppressed. `record` is no more concrete than `point`. **The check can only
// catch abstraction it already has the word for**, and the fix is not a longer list:
// abstract nouns are an open class, and every word added moves the same defect one word
// further out. See kristy-ios/CLAUDE.md §1.8e/§1.8f — this is the third link in a chain
// where each checker was written for what the previous one missed and then missed in the
// same direction.
//
// A THIRD SHAPE THIS CANNOT SEE AT ALL: an abstract noun as SUBJECT with a lexical verb
// of existing — "The real food lives on the perimeter." No copula, so the COPULA gate
// never opens, and the abstraction is in the subject rather than the payload. It is
// shipped copy on the frozen web client. Deliberately NOT given a third checker.
const COPULA = /\b(is|are|was|were)\b/i;

// Nouns that name a relationship rather than a thing. A clause whose only payload is one
// of these has told the reader nothing they can do.
const ABSTRACT_PAYLOAD = new Set([
  'membership', 'point', 'difference', 'deal', 'idea', 'trick', 'answer', 'reason',
  'catch', 'question', 'secret', 'purpose', 'upgrade', 'value', 'benefit', 'advantage',
]);

// Words that carry no concreteness of their own, so they cannot rescue a clause: bare
// gerunds of doing, and the pronoun-ish subjects these lines lean on.
const NOT_CONCRETE = new Set([
  'keeping', 'saving', 'having', 'being', 'doing', 'getting', 'making', 'taking',
  'that', 'this', 'these', 'those', 'one', 'ones', 'yours', 'ours', 'theirs',
]);

/**
 * The copula-abstraction hits in a string. Empty is the passing state.
 * @returns {Array<{clause:string, noun:string}>}
 */
export function copulaAbstraction(text) {
  const s = String(text || '').trim();
  const parts = s.split(/(?:\.|;|—)\s+/).map((p) => p.trim()).filter((p) => p.split(/\s+/).length >= 2);
  const hits = [];
  for (let i = 1; i < parts.length; i++) {
    const p = parts[i];
    if (!COPULA.test(p)) continue;
    const toks = contentTokens(p);
    const abstract = toks.filter((t) => ABSTRACT_PAYLOAD.has(t));
    if (!abstract.length) continue;
    const concrete = toks.filter((t) => !ABSTRACT_PAYLOAD.has(t) && !NOT_CONCRETE.has(t));
    if (concrete.length === 0) hits.push({ clause: p, noun: abstract[0] });
  }
  return hits;
}

export function nameables(text) {
  const s = String(text || '');
  const propers = s.match(/\b[A-Z][a-z]+(?:\s+(?:by\s+)?[A-Z][A-Za-z]+)+\b/g) || [];
  const quoted = [...s.matchAll(/[‘“]([^’”]{2,40})[’”]/g)].map((m) => m[1].trim());
  return [...new Set([...propers, ...quoted])];
}

/**
 * Where a card appears to disagree with itself. Empty is the passing state, and a hit is
 * a prompt to look, never a verdict.
 *
 * @returns {Array<{code:string, detail:string}>}
 */
export function contradictions(card) {
  const out = [];
  const verdict = [card?.headline, card?.do ?? card?.do_line].filter(Boolean).map(String);
  const elsewhere = {
    why: card?.why,
    detail: card?.detail,
    kristy_take: card?.kristy_take,
    look_for: (card?.look_for || []).join(' · '),
    watch_out: (card?.watch_out || []).join(' · '),
    labels_decoded: (card?.labels_decoded || []).map((l) => `${l?.term} ${l?.meaning}`).join(' · '),
  };

  // 1. Exclusivity in the verdict, enumeration everywhere else.
  const exclusive = verdict.find((t) => EXCLUSIVITY.test(t));
  if (exclusive) {
    for (const [field, text] of Object.entries(elsewhere)) {
      const named = nameables(text);
      if (named.length >= 2) {
        out.push({
          code: 'CONTRADICTION_EXCLUSIVITY',
          detail: `"${exclusive.match(EXCLUSIVITY)[0]}" in the verdict, but ${field} names ${named.length}: ${named
            .slice(0, 3)
            .map((n) => `"${n}"`)
            .join(', ')}`,
        });
      }
    }
  }

  return out;
}

/**
 * Report the tics on a card. Never part of lintCard — these do not gate anything.
 */
export function voiceTics(card) {
  const fields = {
    headline: card?.headline,
    do: card?.do ?? card?.do_line,
    why: card?.why,
    tier_note: card?.tier_note,
  };
  const out = [];
  for (const [field, text] of Object.entries(fields)) {
    if (!text) continue;
    for (const h of antithesisChime(text)) {
      out.push({ code: 'TIC_ANTITHESIS', field, detail: `"${h.clause}" echoes "${h.echo}" and adds nothing` });
    }
  }
  out.push(...contradictions(card).map((c) => ({ ...c, field: 'card' })));
  return out;
}

/* ═══════════════════════════ One verdict per headline ═══════════════════════════ */

// THE HEDGE MAY NOT LIVE IN THE VERDICT. The corpus shipped nine headlines shaped
// "standard, then retreat" — "Wild if it is in reach. Farmed or nothing, buy the farmed",
// "Grass-fed when the price is fair. Otherwise regular beef", "Worth it if the budget
// stretches. Otherwise the plain carton". Each is two verdicts where the second cancels
// the first, and Kristy negotiates with herself before the shopper has asked. The
// standard goes in the headline undiluted; the fallback moves to look_for or watch_out,
// where it reads as practical rather than as a retreat.
//
// A TWO-CLAUSE HEADLINE IS NOT THE DEFECT, and this is the whole difficulty. Four
// headlines split by TYPE or USE CASE and are correct:
//
//   "Organic on thin-skinned produce. Conventional on anything peeled."
//   "Meaningful on beef and dairy. A freebie on chicken and pork."
//   "Pay for grade on a quick-cooked steak. Skip it on anything braised."
//   "80/20 for burgers. 90/10 for anything you drain."
//
// Those are discrimination — the standard differs by what is in your hand. Banning two
// clauses would delete them along with the hedges, so the check tests WHAT THE SECOND
// CLAUSE IS CONDITIONED ON instead. A condition about the FOOD is discrimination. A
// condition about the SHOPPER'S CIRCUMSTANCES — their budget, what the store happens to
// stock, how much time they have — is the retreat.

// The fallback stated outright. `otherwise` and `unless` have no innocent reading in a
// verdict, and neither does the "X or nothing, buy the X" construction.
//
// "or nothing" needs the comma or a following imperative: "Clean seawater or nothing
// means yes" is a description of a smell, not a fallback, and it was the false positive
// that made a bare /or nothing/ useless.
const FALLBACK_OUTRIGHT = [
  [/\botherwise\b/i, 'otherwise'],
  [/\bunless\b/i, 'unless'],
  [/\bor nothing,/i, 'or nothing,'],
  [/\bor nothing\b\s+(buy|take|get|grab)\b/i, 'or nothing + imperative'],
];

// A conditional marker. On its own this proves nothing — "Wash it when you eat it" is
// temporal and correct — so it only counts alongside a circumstance below.
export const LADDER_OPENER = /^If you can['’]t get ([^:]{2,40}): /;
const CONDITIONAL = /\b(if|when|whenever|where|as long as|provided)\b/i;

// THE SHOPPER'S CIRCUMSTANCES. This list is the load-bearing part of the check: a
// condition drawn from here is about the person, not the food, and a standard that bends
// to it is a standard being withdrawn.
const CIRCUMSTANCE =
  /\b(budget|price|prices|priced|afford|affordable|cost|costs|money|cheap|cheaper|expensive|worth it|stretch(es)?|fair|reasonable|close)\b|\b(in reach|available|in stock|they have it|the store (has|carries|stocks)|it is there|there is (any|some)|you can find|carries it)\b|\b(time|hurry|busy|quick enough|convenience|convenient)\b|\b(you want|you like|you prefer|if that matters|you care)\b/i;

// A QUESTION IN THE HEADLINE IS A CONDITIONAL FRAME. "Paying grass-fed prices? Buy
// grass-FINISHED" reads as firm and is still "if you are paying…". The card states the
// standard for everyone or it is not a standard.
const QUESTION_FRAME = /\?/;

// THE RETREAT WITH NO KEYWORD. "Whole milk. Buy the one the household actually drinks."
// carries no conditional at all and does the identical thing: names the pick, then hands
// the choice back. A keyword scan misses it, so the deference phrasing is matched
// directly.
const DEFERENCE = [
  [/\bwhatever\b/i, 'whatever'],
  [/\bwhichever\b/i, 'whichever'],
  [/\bthe one (you|they|the household|your|he|she)\b/i, 'the one you/they/the household'],
  [/\bup to you\b/i, 'up to you'],
  [/\byour call\b/i, 'your call'],
  [/\bwhat works (for|best)\b/i, 'what works for'],
  [/\bactually (drinks?|eats?|uses?|cooks?)\b/i, 'what they actually drink/eat'],
];

/**
 * The hedges in a headline. Empty is the passing state.
 *
 * @returns {Array<{kind:string, detail:string}>}
 */
export function headlineHedge(headline) {
  const h = String(headline || '').trim();
  if (!h) return [];
  const hits = [];

  for (const [re, name] of FALLBACK_OUTRIGHT) {
    if (re.test(h)) hits.push({ kind: 'fallback', detail: `"${name}" states a fallback in the verdict` });
  }
  const cond = h.match(CONDITIONAL);
  const circ = h.match(CIRCUMSTANCE);
  if (cond && circ) {
    hits.push({
      kind: 'circumstance',
      detail: `"${cond[0]}" conditions the verdict on "${circ[0]}" — the shopper's circumstances, not the food`,
    });
  }
  if (QUESTION_FRAME.test(h)) {
    hits.push({ kind: 'question', detail: 'a question frames the verdict as conditional' });
  }
  for (const [re, name] of DEFERENCE) {
    const m = h.match(re);
    if (m) hits.push({ kind: 'deference', detail: `"${m[0]}" (${name}) hands the decision back to the shopper` });
  }
  return hits;
}

/* ═══════════════════════════ Accuracy: the false mechanisms ═══════════════════════════ */

// FIRMER IS NOT LOOSER WITH FACTS. Kristy's authority comes from being right, and one
// wrong claim costs more than ten soft ones. Each rule here is a claim that would make a
// TRUE position sound more convincing by resting it on something false — which is the one
// way a firmer voice can do real damage.
//
// These are not hypothetical. The accurate case against farmed salmon is strong on its
// own: a feed-driven fat profile with a far worse omega-3 to omega-6 ratio, astaxanthin
// in the ration because the flesh is otherwise gray, sea lice and their treatments, and
// antibiotic use that varies enormously by country. None of it needs propping up.

const FARMED_FISH = /\b(farmed|farm-raised|aquaculture|penned)\b/i;
const SALMON_CONTEXT = /\b(salmon|farmed fish|aquaculture)\b/i;

const MECHANISMS = [
  {
    id: 'salmon_hormones',
    // FALSE. Growth hormones are not used in commercial salmon farming anywhere. The
    // claim is a persistent myth and it is the fastest way to lose the whole argument.
    test: (t) => SALMON_CONTEXT.test(t) && /\bhormones?\b/i.test(t),
    why: 'growth hormones in farmed salmon — they are not used in commercial salmon farming, and the claim is false',
  },
  {
    id: 'salmon_omega3_amount',
    // The claim is ALWAYS the RATIO, never the amount. Farmed salmon is fatter, so a
    // serving often carries as much total omega-3 as wild or more. "Less omega-3" is
    // false and it is the easy thing to reach for.
    test: (t) =>
      FARMED_FISH.test(t) && /\b(less|lower|fewer|little|hardly any|not much|no real)\s+omega-3\b/i.test(t),
    why: 'farmed fish having less omega-3 — the claim is about the omega-3 to omega-6 RATIO, never the amount',
  },
  {
    id: 'antibiotics_flat',
    // Antibiotic use in aquaculture varies enormously by country of origin: Norwegian
    // farming runs close to zero on the back of vaccination, others run far higher. A
    // flat claim is false for the best producers and unfalsifiable for the rest.
    test: (t) =>
      /\b(full of|pumped (full )?of|loaded with|riddled with|swimming in|dosed with)\s+antibiotics\b/i.test(t),
    why: 'a flat antibiotic claim — use varies enormously by country of origin and must be framed that way',
  },
  {
    id: 'antibiotics_unframed',
    // Naming antibiotics on a farmed-fish card WITHOUT the country framing is the same
    // claim by omission. This is a required-context rule rather than a banned phrase,
    // because the defect is what the sentence leaves out.
    test: (t) =>
      FARMED_FISH.test(t) &&
      /\bantibiotic/i.test(t) &&
      !/\b(countr\w+|origin|varies|varying|vary|by producer|norway|norwegian|chile|chilean)\b/i.test(t),
    why:
      'antibiotics named on a farmed-fish card with no country framing — always "varies by country of origin", ' +
      'never a flat claim',
  },
];

/**
 * The false mechanisms on a card. Empty is the passing state.
 * @returns {Array<{id:string, why:string}>}
 */
export function falseMechanisms(card) {
  const text = [
    card?.headline,
    card?.do ?? card?.do_line,
    card?.why,
    card?.detail,
    card?.kristy_take,
    card?.tier_note,
    ...(card?.look_for || []),
    ...(card?.watch_out || []),
    ...(card?.labels_decoded || []).map((l) => `${l?.term} ${l?.meaning}`),
  ]
    .filter(Boolean)
    .join('  ');
  return MECHANISMS.filter((m) => m.test(text)).map(({ id, why }) => ({ id, why }));
}

/* ═══════════════════════════ Imperative ═══════════════════════════ */

// A `do` line is an instruction, so its first token is a verb. Detecting that properly
// needs a part-of-speech tagger; an explicit list is more honest and is inspectable in
// review. Adding a verb is a deliberate act — which is the point, because the failure
// this catches is a line that opens "Organic is generally…" and describes instead of
// instructing.
export const IMPERATIVE_VERBS = new Set([
  'ask', 'avoid', 'bring', 'buy', 'call', 'carry', 'check', 'choose', 'compare', 'count',
  'cover', 'decide', 'fill', 'find', 'flip', 'freeze', 'get', 'grab', 'hold', 'ignore',
  'keep', 'leave', 'lift', 'look', 'move', 'open', 'pass', 'pick', 'pop', 'pour', 'press',
  'pull', 'push', 'put', 'read', 'reach', 'rinse', 'rotate', 'rub', 'scan', 'scoop',
  'scrub', 'search', 'skip', 'smell', 'sort', 'spend', 'split', 'squeeze', 'start', 'stop',
  'store', 'swap', 'take', 'taste', 'tip', 'touch', 'trace', 'try', 'turn', 'walk', 'wash',
  'watch', 'weigh', 'wrap',
  // The sensory batch. Produce and the counters are judged by hand and nose, and the list
  // was rejecting the most natural verbs for it — a generated cantaloupe card opened with
  // "Sniff" and cost a full retry for being right.
  'peel', 'shake', 'sniff', 'tap', 'thump',
  // The KITCHEN batch, added with the `home` technique cards on 2026-08-02. This list was
  // built for aisle actions — read, check, look, take — and a card whose observable is at
  // the stove has a different vocabulary. Every one of these was a card that could not
  // state its own action: the baking-soda card opens "Soak", the bean card "Stir", the
  // greens card "Trim", the freezing card "Blanch", the spice card "Toast". Adding a verb
  // stays a deliberate act, which is the point of the list being explicit.
  'blanch', 'soak', 'stir', 'toast', 'trim',
]);

export const firstToken = (s) =>
  String(s || '').trim().split(/\s+/)[0].replace(/[^A-Za-z’'-]/g, '').toLowerCase();

/* ═══════════════════════════ The observable ═══════════════════════════ */

// RULING 4, the defect that recurs: when the printed word a shopper looks for sits in the
// headline, every honest `do` line restates it, and the card wastes its most valuable
// line. Detected as a distinctive term appearing in BOTH.
//
// "Distinctive" is doing real work. A headline and a `do` line about the same food will
// always share ordinary words, and flagging those would make the check useless. So a
// shared term counts only when it is specific enough to BE the observable: hyphenated
// ("soy-free", "grass-finished"), or a long-enough word that is neither grammar nor the
// name of a container, a surface, or the act of reading one.

const GRAMMAR = new Set([
  'and', 'any', 'anything', 'are', 'because', 'been', 'before', 'both', 'but', 'does',
  'every', 'for', 'from', 'has', 'have', 'into', 'its', 'means', 'more', 'most', 'much',
  'never', 'not', 'nothing', 'only', 'over', 'own', 'same', 'says', 'should', 'still',
  'than', 'that', 'the', 'their', 'them', 'then', 'there', 'they', 'this', 'through',
  'under', 'until', 'what', 'when', 'where', 'which', 'while', 'with', 'without', 'you',
  'your',
  // Rhetoric — long enough to look distinctive, but they name nothing in a store.
  'actually', 'anyway', 'always', 'entirely', 'explicitly', 'generally', 'implies',
  'instead', 'otherwise', 'really', 'simply', 'usually',
]);

// Containers, surfaces, and the act of consulting one. Two cards about the same aisle
// share these constantly and it means nothing — a `do` line has to name a package.
const NEUTRAL = new Set([
  'aisle', 'back', 'bag', 'bottle', 'box', 'bunch', 'can', 'canister', 'carton', 'case',
  'claim', 'claims', 'clamshell', 'container', 'counter', 'date', 'front', 'ingredient',
  'ingredients', 'jar', 'jug', 'label', 'line', 'list', 'lid', 'package', 'packet',
  'panel', 'piece', 'pound', 'price', 'print', 'printed', 'produce', 'seal', 'shelf',
  'side', 'sticker', 'store', 'tag', 'tub', 'wording', 'word', 'words', 'wrapper',
  // the verbs of consulting one
  'buy', 'check', 'find', 'look', 'read', 'take',
]);

const MIN_DISTINCTIVE = 6;

const termsOf = (s) =>
  new Set(
    String(s || '')
      .toLowerCase()
      .replace(/[“”‘’]/g, '')
      .match(/[a-z][a-z-]{2,}/g) || []
  );

const isDistinctive = (t) =>
  !GRAMMAR.has(t) && !NEUTRAL.has(t) && (t.includes('-') || t.length >= MIN_DISTINCTIVE);

// The terms sitting inside quotation marks — by construction, the printed word a shopper
// hunts for. This is the observable in its least ambiguous form.
//
// A quoted QUESTION is excluded: "was this previously frozen?" is something the shopper
// says out loud at the counter, not something printed on a package. Counting speech as a
// printed observable flagged a perfectly good card.
function quotedTerms(s) {
  const out = new Set();
  for (const m of String(s || '').matchAll(/[“"']([^”"']{2,60})[”"']|‘([^’]{2,60})’/g)) {
    const span = m[1] || m[2];
    if (span.trim().endsWith('?')) continue;
    for (const t of termsOf(span)) out.add(t);
  }
  return out;
}

/**
 * The distinctive terms a headline and a `do` line share. Empty is the passing state.
 *
 * TWO SIGNALS, because one alone is either too loose or too tight:
 *
 *   · A shared term that is QUOTED on either side. A quoted term IS the printed word;
 *     if the headline already handed it over, the `do` line has nothing left to add.
 *     One is enough.
 *   · TWO OR MORE shared distinctive terms, quoted or not. One shared subject noun is
 *     normal and healthy — a card about grass-fed beef says "grass-fed" twice and the
 *     `do` line still earns its place by naming the cut. Two shared terms means the line
 *     is orbiting the headline rather than adding to it.
 */
export function sharedObservables(headline, doLine) {
  const h = termsOf(headline);
  const d = termsOf(doLine);
  const shared = [...h].filter((t) => d.has(t)).filter(isDistinctive);
  if (!shared.length) return [];

  const quoted = new Set([...quotedTerms(headline), ...quotedTerms(doLine)]);
  const sharedQuoted = shared.filter((t) => quoted.has(t));

  if (sharedQuoted.length) return sharedQuoted;
  return shared.length >= 2 ? shared : [];
}

/* ═══════════════════════════ The pick ═══════════════════════════ */

// A PICK IS ONE SENTENCE ABOUT THE FOOD'S SURFACE, AND NOTHING ELSE.
//
// `kind: 'pick'` is a KB entry that carries the one line a shopper reads in the store on a
// list row that has no question card — carrots, garlic, milk. It is not a card: no
// headline, no depth, no ask, no sheet. It is never migrated to `counter_cards` and never
// served by a counter door; it travels on the row. So it clears a different bar from a
// card, and a stricter one, because nothing downstream re-reads it: no tier sentence says
// what kind of claim it is, no depth carries the evidence, no `why` explains it. The line
// has to be true on its face, which means it may only describe what a shopper can SEE,
// FEEL, SMELL or READ on the food or its label — what happens to the food, never to the
// body.
//
// THE VETO VOCABULARY IS EXPLICIT, like IMPERATIVE_VERBS, and for the same reason: a
// part-of-speech judgment about "is this sentence about the body" cannot be reviewed, and a
// list can. Matching is by word boundary, case-insensitive, base form plus `s`/`es` (a
// plural or a third person) and `ing` (the participle a claim hides in: "boosting",
// "supporting"). It does NOT reach into `ed` on purpose: "cured" and "treated" are
// processing words on the meat and produce counters ("dry-cured", "treated with wax") and
// vetoing them would cost the mechanical line the list exists to allow. The outcome nouns
// are the first net — a health claim names the thing it claims to help, and "lowers blood
// sugar" trips on `blood` and `sugar` before it ever needs `lower` — so the verb list is
// the second net, not the only one. Adding a word stays a deliberate act.
//
// KNOWN COST, accepted: the veto is vocabulary, not sense. "weight" is bodily here even
// when an author means the bulb's heft, and "lower" is vetoed even for the lower shelf.
// Write "heavy for its size" and "bottom shelf". A veto that tried to tell the senses
// apart would be a guess dressed as a rule.
//
// `fat` IS NOT ON THE LIST, deliberately. Marbling, the fat cap and "the white should be
// bright, not yellow" are the mechanical read at the meat counter, and a pick for a
// ribeye or a pork shoulder has to be able to say it. "Low-fat" as a health claim trips on
// `health` or the outcome it is attached to, not on the word `fat`.
export const MECHANICAL_VETO = {
  // The body and its outcomes. Any of these in a pick line makes the sentence a claim about
  // the shopper rather than a description of the food, and a claim needs the tier, the
  // source and the depth a pick does not carry. `health` and `immunity` are the nouns the
  // vaguest claims hang on ("for the health benefits", "for immunity").
  body: [
    'heart', 'blood', 'sugar', 'cholesterol', 'inflammation', 'immune', 'immunity', 'gut',
    'digestion', 'weight', 'cancer', 'disease', 'health', 'healthy',
  ],
  // Nutrition vocabulary. A pick may say a yolk is deep orange; it may not say why that is
  // good for you. The moment a line names a nutrient, a calorie, a sodium level or "energy"
  // it is asserting what the food delivers, which is the ingredient KB's job and the verdict
  // engine's, never a list row's. A label's own printed numbers are a scan, not a pick.
  nutrition: [
    'nutrient', 'vitamin', 'mineral', 'protein', 'fiber', 'carb', 'calorie', 'sodium', 'energy',
    'antioxidant', 'detox', 'toxin',
  ],
  // The no-treatment verbs, both directions (non-negotiable #3 is symmetric): a food that
  // treats, cures, prevents, heals, lowers, boosts, fights, protects or supports anything,
  // and a food that CAUSES anything. Kristy is a coach, not a doctor, and a list row is the
  // last place in the app anyone would defer to one.
  treatment: ['treat', 'cure', 'prevent', 'heal', 'lower', 'boost', 'cause', 'fight', 'protect', 'support'],
};

const VETO_WORDS = Object.values(MECHANICAL_VETO).flat();
const VETO_RE = new RegExp(`\\b(${VETO_WORDS.join('|')})(s|es|ing)?\\b`, 'i');

/** The first vetoed word in a line, or null. */
export function mechanicalVeto(line) {
  const m = String(line || '').match(VETO_RE);
  return m ? m[0] : null;
}

// The line's word bar. A card's do line is 14; a pick line has no headline above it to
// share the work with, so it gets two more and no more — past this it is a paragraph a
// shopper reads with one hand while holding the thing it describes.
export const MAX_PICK_WORDS = 16;

// A pick is a food, so it files under a counter. `label_terms` is a reference section, the
// same exclusion the list matcher applies at attach (NON_AISLE_SECTIONS in listMatch.js): a
// pick filed there could never reach a row and would be dead on arrival.
const NON_AISLE_SECTION = 'label_terms';

// Fields a pick may not carry. A pick with a headline or a depth field is a card that has
// dodged the card's bar by declaring itself something else — and a field on a pick that no
// surface renders is a claim nobody reviews. The list is every authored card field, plus
// the paid boundary's own list so a field added to the depth is forbidden here without a
// second edit. `sources` is the exception: it is a depth field on a card because it is
// PAID there, and it is REQUIRED on a pick because it is the only thing that separates an
// authored line from a remembered one. Nothing on a pick is served, so paid/free does not
// apply to it.
export const PICK_FORBIDDEN_FIELDS = new Set([
  'asked_as', 'headline', 'why', 'tier_note', 'look_for', 'watch_out', 'detail',
  'kristy_take', 'labels_decoded', 'cart_pick', 'short_answer', 'buying_tips', 'question',
  'evidence_tier', 'instead', 'card_why', 'eyebrow_short', 'pick_steps', 'science',
  ...DEPTH_FIELDS.filter((f) => f !== 'sources'),
]);

// Bare noun: lowercase, letters, spaces and hyphens, at most three words. An alias is
// matched by whole-phrase containment against what a shopper TYPES on a list, and a list
// says "carrots", never "how do I pick carrots".
const MAX_PICK_ALIAS_WORDS = 3;
const BARE_NOUN = /^[a-z][a-z\s-]*$/;

// The number pair, by a simple suffix relation and nothing cleverer: `s`, `es`, or `y` to
// `ies`. Not a stemmer. A shopper writes "carrots" and "carrot" both, and "cherries" and
// "cherry" both, and each has to hit; a stemmer would admit pairs no shopper types.
const PLURALS_OF = (a) => [
  `${a}s`,
  `${a}es`,
  a.endsWith('y') ? `${a.slice(0, -1)}ies` : null,
].filter(Boolean);

// Words that describe a food without naming one. A pick alias made only of these ("frozen",
// "organic") is a subject-less alias: the matcher walks aliases by containment, so it would
// attach the pick to any row carrying the word. Explicit list, widened deliberately.
const MODIFIER_WORDS = new Set([
  'frozen', 'canned', 'tinned', 'dried', 'dry', 'fresh',
  'organic', 'raw', 'whole', 'wild', 'farmed', 'pasteurized', 'unpasteurized',
]);
const onlyModifiers = (a) => a.split(/[\s-]+/).filter(Boolean).every((w) => MODIFIER_WORDS.has(w));

const hasUrl = (s) => /https?:\/\/\S+/.test(String(s || ''));

/**
 * Lint one pick entry. Empty is the passing state.
 * @returns {Array<{code:string, detail:string}>}
 */
// Zero first person (VOICE_SPEC). `I` is case-sensitive so "i" inside nothing trips;
// `us` is lowercase-only so a country of origin ("US grown") does not read as a pronoun.
const hasFirstPerson = (line) =>
  /\bI\b/.test(line) || /\b(me|my|mine|we|our|ours)\b/i.test(line) || /\bus\b/.test(line);

export function lintPick(entry) {
  const out = [];
  const fail = (code, detail) => out.push({ code, detail });
  const e = entry || {};

  // ── Required ──
  for (const f of ['id', 'title', 'category', 'decision']) {
    if (!String(e[f] || '').trim()) fail('PICK_FIELD_MISSING', `a pick needs ${f}`);
  }

  // ── Forbidden ──
  for (const f of Object.keys(e)) {
    if (PICK_FORBIDDEN_FIELDS.has(f)) {
      fail('PICK_FIELD_FORBIDDEN', `"${f}" is a card field — a pick is one sentence, not a card`);
    }
  }

  // ── The food, bare ──
  const title = String(e.title || '').trim();
  if (title && (words(title) > 4 || /[.!?,;:]/.test(title))) {
    fail('PICK_TITLE_NOT_BARE', `the title is the food, bare: "${title}"`);
  }

  // ── Filed under a counter ──
  const category = String(e.category || '').trim();
  if (category) {
    const section = sectionForCategory(category);
    if (!section) fail('PICK_CATEGORY_UNSECTIONED', `"${category}" maps to no counter section`);
    else if (section === NON_AISLE_SECTION) {
      fail('PICK_CATEGORY_NON_AISLE', `"${category}" files under ${section}, which no list row is ever sorted into`);
    }
  }

  // ── Aliases: bare nouns, both numbers ──
  const aliases = Array.isArray(e.aliases) ? e.aliases.map((a) => String(a || '').trim()).filter(Boolean) : [];
  if (aliases.length < 2) {
    fail('PICK_ALIASES_TOO_FEW', `a pick needs at least 2 bare-noun aliases; got ${aliases.length}`);
  }
  const notBare = aliases.filter((a) => !BARE_NOUN.test(a) || words(a) > MAX_PICK_ALIAS_WORDS);
  if (notBare.length) {
    fail(
      'PICK_ALIAS_NOT_BARE',
      `an alias is what a shopper types on a list — lowercase, ≤${MAX_PICK_ALIAS_WORDS} words: ${notBare.map((a) => `"${a}"`).join(', ')}`
    );
  }
  // A state-bearing pick ("Frozen peas") is about the frozen thing. `stateContradicts` is
  // silent when the ROW names no state, so a bare `peas` alias here would attach the frozen
  // line to a fresh row. Every alias carries the state, or the pick does not ship.
  if (title && statesIn(title).size) {
    const stateless = aliases.filter((a) => !statesIn(a).size);
    if (stateless.length) {
      fail(
        'PICK_ALIAS_DROPS_STATE',
        `the title names a state, so every alias must too: ${stateless.map((a) => `"${a}"`).join(', ')}`
      );
    }
  }
  const subjectless = aliases.filter(onlyModifiers);
  if (subjectless.length) {
    fail(
      'PICK_ALIAS_NO_SUBJECT',
      `an alias must name a food, not only describe one: ${subjectless.map((a) => `"${a}"`).join(', ')}`
    );
  }
  const set = new Set(aliases);
  const paired = aliases.some((a) => PLURALS_OF(a).some((p) => set.has(p)));
  if (aliases.length && !paired) {
    fail(
      'PICK_ALIASES_NO_NUMBER_PAIR',
      'aliases must carry a singular AND its plural (s / es / y→ies) — a list says "carrot" and "carrots" both'
    );
  }

  // ── The line ──
  const line = String(e.decision || '').trim();
  if (line) {
    // Exactly one sentence, closed with a period. Two sentences is a card's summary; a
    // fragment is a label.
    const terminals = (line.match(/[.!?](?=\s|$)/g) || []).length;
    if (terminals !== 1 || !line.endsWith('.')) {
      fail('PICK_LINE_NOT_ONE_SENTENCE', `exactly one sentence ending in a period: "${line}"`);
    }
    if (/\?/.test(line)) fail('PICK_LINE_QUESTION', `a pick states, it never asks: "${line}"`);
    if (words(line) > MAX_PICK_WORDS) {
      fail('PICK_LINE_TOO_LONG', `${words(line)}w > ${MAX_PICK_WORDS}: ${line}`);
    }
    if (hasFirstPerson(line)) {
      fail('PICK_LINE_FIRST_PERSON', `no I/me/my/we/our on any line Kristy speaks: "${line}"`);
    }
    if (/—/.test(line)) fail('PICK_LINE_EM_DASH', `no em-dash asides: "${line}"`);
    // No digits. A number is a measurement, and a measurement is a claim with a source a
    // list row cannot show. "Heavy for its size", never "over 200g".
    if (/\d/.test(line)) fail('PICK_LINE_DIGIT', `no digits on a pick line: "${line}"`);
    const vetoed = mechanicalVeto(line);
    if (vetoed) {
      fail(
        'PICK_LINE_NOT_MECHANICAL',
        `"${vetoed}" is about the body, not the food. A pick describes surface, weight, smell, ` +
          `color, firmness, date or a label word — what happens to the food, never to the shopper: "${line}"`
      );
    }
    // Same house copy as every other line.
    const brit = britishSpellings(line);
    if (brit.length) fail('COPY_BRITISH', `British spelling: ${brit.map((w) => `"${w}"`).join(', ')} — the corpus is American`);
    if (STRAIGHT_QUOTE.test(line)) fail('COPY_STRAIGHT_QUOTE', `a straight quote or apostrophe in: "${line}" — the corpus uses “ ” and ’`);
  }

  // ── Sources, each fetchable ──
  // A URL is the bar because a URL can be fetched, and "every source gets fetched before it
  // ships" is the rule. A source named from memory has no URL to give.
  const sources = Array.isArray(e.sources) ? e.sources : [];
  if (!sources.length) fail('PICK_SOURCES_MISSING', 'a pick needs at least one source, with a URL');
  const noUrl = sources.filter((s) => !(hasUrl(s) || hasUrl(s?.url)));
  if (noUrl.length) {
    fail('PICK_SOURCE_NO_URL', `every pick source carries a URL it was fetched from; ${noUrl.length} of ${sources.length} do not`);
  }

  return out;
}

/* ═══════════════════════════ Per-card ═══════════════════════════ */

/**
 * Lint one card — curated or generated — or one pick.
 * @returns {Array<{code:string, detail:string}>} empty when the card passes.
 */
export function lintCard(card) {
  // A pick is not a card and clears a different bar. Branching here rather than at the
  // call site means the generation path, the corpus tests and any future door all reach
  // the pick rules through the one function they already call.
  if (card?.kind === 'pick') return lintPick(card);

  const out = [];
  const fail = (code, detail) => out.push({ code, detail });

  const headline = String(card?.headline || '').trim();
  const doLine = String(card?.do ?? card?.do_line ?? '').trim();

  if (!headline) fail('HEADLINE_MISSING', 'the card has no verdict');
  else if (words(headline) > MAX_HEADLINE_WORDS) {
    fail('HEADLINE_TOO_LONG', `${words(headline)}w > ${MAX_HEADLINE_WORDS}: ${headline}`);
  }

  // ONE VERDICT PER HEADLINE. The fallback belongs in look_for or watch_out.
  for (const h of headlineHedge(headline)) {
    fail('HEADLINE_HEDGED', `${h.detail}. State the standard undiluted; move the fallback to watch_out`);
  }

  // Accuracy outranks firmness. A claim that needs a false mechanism is a wrong claim.
  for (const m of falseMechanisms(card)) {
    fail('CLAIM_FALSE_MECHANISM', m.why);
  }

  if (!doLine) {
    fail('DO_MISSING', 'the card has no physical action');
  } else {
    if (words(doLine) > MAX_DO_WORDS) {
      fail('DO_TOO_LONG', `${words(doLine)}w > ${MAX_DO_WORDS}: ${doLine}`);
    }
    const verb = firstToken(doLine);
    if (!IMPERATIVE_VERBS.has(verb)) {
      fail('DO_NOT_IMPERATIVE', `opens with "${verb}", which is not a known imperative verb`);
    }
  }

  // A GENERATED card must carry aliases, because aliases are the only way it can ever be
  // RETRIEVED again. The deterministic matcher scores alias phrases; a card with none
  // scores zero against every future question, so the next shopper asking the identical
  // thing regenerates it. That is not a cosmetic gap — it is an unbounded spend loop and
  // a corpus that forks into near-duplicates of the same answer.
  if (card?.source === 'generated') {
    const aliases = Array.isArray(card.aliases) ? card.aliases.filter((a) => String(a || '').trim()) : [];
    if (aliases.length < 2) {
      fail(
        'ALIASES_MISSING',
        `a generated card needs at least 2 aliases to be findable again; got ${aliases.length}`
      );
    }

    // AN ALIAS HAS TO BE SHORT, and this is not a style rule. The matcher looks for each
    // alias as a run of words INSIDE the question, so a full sentence never matches
    // anything: "how to tell if a cantaloupe is ripe" is not contained in "how do I pick a
    // good cantaloupe". The first generated card shipped six aliases, every one of them a
    // sentence, and it regenerated on every ask because none could ever hit.
    const longOnes = aliases.filter((a) => words(a) > MAX_ALIAS_WORDS);
    if (longOnes.length) {
      fail(
        'ALIASES_TOO_LONG',
        `an alias is matched as a phrase inside a question, so it must be short. Over ${MAX_ALIAS_WORDS} words: ${longOnes.map((a) => `"${a}"`).join(', ')}`
      );
    }
    if (!aliases.some((a) => words(a) <= 2)) {
      fail(
        'ALIASES_NO_SHORT_FORM',
        'at least one alias must be one or two words — usually the bare subject noun, which is the most likely hit'
      );
    }
  }

  // Copy hygiene, across every readable field. A card is one voice, so a British spelling
  // in watch_out is the same defect as one in the headline.
  const copy = [
    headline,
    doLine,
    card?.why,
    card?.tier_note,
    card?.topic,
    card?.eyebrow,
    card?.cta_item,
    card?.detail,
    card?.kristy_take,
    ...(card?.look_for || []),
    ...(card?.watch_out || []),
  ]
    .filter(Boolean)
    .map(String);

  const brit = [...new Set(copy.flatMap(britishSpellings))];
  if (brit.length) {
    fail('COPY_BRITISH', `British spelling: ${brit.map((w) => `"${w}"`).join(', ')} — the corpus is American`);
  }
  const straight = copy.filter((t) => STRAIGHT_QUOTE.test(t));
  if (straight.length) {
    fail(
      'COPY_STRAIGHT_QUOTE',
      `a straight quote or apostrophe in: "${straight[0].slice(0, 60)}…" — the corpus uses “ ” and ’`
    );
  }

  const tierNote = String(card?.tier_note || '').trim();
  if (!tierNote) {
    fail('TIER_NOTE_MISSING', 'the tier has no sentence carrying it on the free surface');
  } else if (echoesRubric(tierNote)) {
    fail(
      'TIER_NOTE_IS_RUBRIC',
      `the tier note repeats the rubric's definition instead of saying why THIS call carries this tier — "${tierNote.slice(0, 70)}…"`
    );
  }

  /* THE NOTE MAY NOT POINT AT THE TIER, because there is nothing to point at. The chip that
     named it was removed on 2026-08-04 (a classification rendered as a badge labels nothing),
     and `tier_note` took over its job on the free summary. Four curated cards — raw_milk,
     raw_kefir, raw_aged_cheese, sprouts_raw — shared one sentence reading "This tier is
     Kristy's sourcing standard", which the moment the chip went became a definite reference
     to a thing no longer on screen. Exactly the referent-less problem the chip had, inverted.

     They also slipped `TIER_NOTE_IS_RUBRIC`: near-paraphrases of the rubric rather than the
     rubric itself, and that check only catches the literal text. This one is structural. */
  if (tierNote && /\b(this|the)\s+tier\b/i.test(tierNote)) {
    fail(
      'TIER_NOTE_SELF_REFERENCE',
      `the tier note says "${tierNote.match(/\b(?:this|the)\s+tier\b/i)[0]}" — nothing on the ` +
        'card names the tier any more, so the phrase points at nothing. Say what the claim ' +
        'IS about this food instead.'
    );
  }

  // The do line a shopper reads is doLines.json's, not the card's own; a card with no entry
  // there (a generated one) renders its own and is skipped.
  const shownDo = doLines[card?.id ?? card?.slug];
  if (tierNote && shownDo && !TIER_NOTE_ORPHANED_PENDING.has(card?.id ?? card?.slug) && tierNoteOrphaned(card, shownDo)) {
    fail(
      'TIER_NOTE_ORPHANED',
      `${card?.id ?? card?.slug}: the tier note was written against the old decision and shares ` +
        `no content word with the do line it sits under — "${shownDo}". Rewrite it to say ` +
        'what kind of claim THAT line is.'
    );
  }

  /* ═══════ `instead` — the free redirect, and the ways it goes wrong ═══════

     THE FIELD EXISTS BECAUSE THE REDIRECT WAS PAID. It lived in `watch_out`, so the shopper
     who could not afford the standard was the one who could not read what to buy instead.
     Moving it free fixes that and opens two new failure modes, both of which this catches,
     because a dedicated field is the likeliest place for each of them to appear.

     ⚠️ ONE: IT NAMES A LESSER VERSION OF THE SAME THING. That is the defect the field was
     built to end — "if it is farmed or nothing, buy the farmed" lowers the bar rather than
     redirecting, and by the salmon card's own argument farmed Atlantic is a different
     product. An `instead` names a DIFFERENT thing: sardines, canned wild, mackerel.
     Detected structurally rather than by vocabulary: if the redirect leads with a hedge, or
     repeats the subject the headline already rejected, it is not an instead.

     ⚠️ TWO: IT READS AS CO-EQUAL. VOICE_SPEC names this as the way the rule breaks from the
     other end — the moment the second-best sounds like an equal option, the card has two
     verdicts again and "one verdict per headline" is broken one field down. */
  const instead = String(card?.instead || '').trim();
  if (instead) {
    if (words(instead) > MAX_INSTEAD_WORDS) {
      fail('INSTEAD_TOO_LONG', `${words(instead)}w > ${MAX_INSTEAD_WORDS}: the redirect is one sentence, not a second card`);
    }

    // A conditional opening is the hedge relocated. "If it is farmed or nothing…" is the
    // shape; the redirect states what to buy, it does not negotiate about whether to.
    // The ladder opener "If you can't get raw: …" (Devon, 2026-10-16) names the best, not the
    // shopper's circumstances, so it is stripped before the check; what follows still answers to it.
    // The exemption holds only while the named best is a food: "raw when in a hurry" is the hedge back in the opener.
    const ladder = instead.match(LADDER_OPENER);
    const redirect =
      ladder && !CONDITIONAL.test(ladder[1]) && !CIRCUMSTANCE.test(ladder[1]) ? instead.slice(ladder[0].length) : instead;
    if (CONDITIONAL.test(redirect.split(/[.,;]/)[0] || '')) {
      fail(
        'INSTEAD_HEDGED',
        `the redirect opens on a condition — "${instead.slice(0, 60)}…". Name what to buy instead; ` +
          'the condition ("when the standard is not there") is what the field already means.'
      );
    }

    // CO-EQUAL LANGUAGE. "just as good", "either works", "equally" — each makes the fallback
    // a second verdict, which is the failure VOICE_SPEC warns about by name.
    if (CO_EQUAL.test(instead)) {
      fail(
        'INSTEAD_CO_EQUAL',
        `"${instead.match(CO_EQUAL)[0]}" makes the redirect an equal option. The headline is the ` +
          'answer; this is what to do when the answer is not there.'
      );
    }

    /* ⚠️ THE REDIRECT MAY NOT BE THE THING THE HEADLINE JUST REFUSED. This is the structural
       version of "a different thing, not a lesser version". The salmon headline rejects
       "farmed"; a redirect containing "farmed" is the card disagreeing with itself one field
       apart — which VOICE_SPEC states as the test for whether a fallback clears the floor.
       Compared on DISTINCTIVE words only, so "salmon" appearing in both is fine and
       "farmed" in both is not. */
    const refused = refusedTerms(headline);
    const echoed = refused.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(instead));
    if (echoed.length) {
      fail(
        'INSTEAD_ECHOES_REFUSED',
        `the redirect names ${echoed.map((t) => `"${t}"`).join(', ')}, which the headline rejects. ` +
          'That is a lesser version of the same thing, not an instead.'
      );
    }
  }

  if (headline && doLine) {
    const shared = sharedObservables(headline, doLine);
    if (shared.length) {
      fail(
        'OBSERVABLE_IN_BOTH',
        `${shared.map((t) => `"${t}"`).join(', ')} appears in the headline AND the do line — ` +
          'the headline keeps the verdict, the observable moves down'
      );
    }
  }

  // K13: the aisle-readability bar (VOICE_SPEC "Readable in the aisle") is fail-level for every card.
  for (const f of readability(card)) fail(f.code, f.field ? `${f.field}: ${f.detail}` : f.detail);
  return out;
}

/* ═══════════════════════════ Corpus-level ═══════════════════════════ */

// An em-dash-then-justification clause is a good shape. Half the corpus wearing it is not:
// eighty cards that all sound alike read as generated even when each line is correct. The
// ceiling is the share the 2026-07-31 sweep landed at (20%) plus room to breathe, so
// ordinary authoring does not trip it and a slide back toward a monoculture does.
export const MAX_EMDASH_SHARE = 0.28;

export const hasEmDashJustification = (doLine) => /—/.test(String(doLine || ''));

// The closing construction: whatever follows the last clause break. "— that percentage is
// water" and "— that percentage is brine" are the same line wearing two nouns.
//
// A line with NO clause break has no closing construction, and returns nothing. This
// matters: comparing whole lines instead flagged every pair of cards that talked about
// the same food, because two meat cards naturally share "ground beef" and "chuck". That
// is shared subject matter, not a repeated construction.
//
// Grammar words are KEPT. The defect is a repeated frame — "that percentage is ___" — and
// the frame is made of exactly the words a content-only bag would throw away.
export function closingConstruction(doLine) {
  const s = String(doLine || '').trim();
  if (!/[—:;]|\.\s+\S/.test(s)) return [];
  const tail = s.split(/[—:;]|\.\s+/).pop() || '';
  return tail.toLowerCase().match(/[a-z][a-z-]+/g) || [];
}

// Two closings collide when they OPEN the same way — the shared frame, not the shared
// vocabulary. "that percentage is water" / "that percentage is brine" share three leading
// tokens and differ only in the final noun.
const MIN_SHARED_PREFIX = 2;

export function sharedPrefix(a, b) {
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  return a.slice(0, i);
}

// A prefix of pure grammar ("it should", "and it is") is not a construction anybody
// notices; it has to carry at least one word with content in it.
const isConstruction = (prefix) =>
  prefix.length >= MIN_SHARED_PREFIX &&
  prefix.some((t) => !GRAMMAR.has(t) && !NEUTRAL.has(t) && t.length >= 3);

// ponytail: widen this scope with each warmth batch; delete the scope when every section is converted.
const WARMTH_PILOT_CATEGORIES = new Set(['beef', 'poultry', 'poultry_eggs', 'meat_counter', 'pork', 'produce']);
const WARMTH_PILOT_IDS = new Set([
  'sandwich_bread', 'sourdough', 'bagels', 'tortillas', 'sprouted_grain_bread',
  'gluten_free_bread', 'bread_aisle',
]);
const WARMTH_CATEGORY_BY_ID = new Map(perimeterKb.entries.map((e) => [e.id, e.category]));

/** Accept authored entries and projected cards, whose decision is named headline. */
export function isWarmthPilot(card) {
  const id = card?.id ?? card?.slug;
  return WARMTH_PILOT_IDS.has(id) ||
    (WARMTH_PILOT_CATEGORIES.has(card?.category ?? WARMTH_CATEGORY_BY_ID.get(id)) &&
      Boolean(card?.decision ?? card?.headline));
}

export function lintOpenerRepetition(cards) {
  const out = [];
  const pilot = (cards || []).filter(isWarmthPilot);
  for (const field of ['decision', 'why', 'kristy_take']) {
    const holders = new Map();
    for (const card of pilot) {
      const text = field === 'decision' ? card.decision ?? card.headline : card[field];
      const tokens = String(text || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '').trim().split(/\s+/);
      if (tokens.length < 3) continue;
      const opener = tokens.slice(0, 3).join(' ');
      if (!holders.has(opener)) holders.set(opener, new Set());
      holders.get(opener).add(card.id ?? card.slug ?? card);
    }
    for (const [opener, ids] of holders) {
      if (ids.size > 3) out.push({ code: 'OPENER_REPEATED', field, opener, ids: [...ids],
        detail: `${ids.size} PILOT cards share the ${field} opener “${opener}”` });
    }
  }
  return out;
}

/**
 * Lint a whole corpus.
 *
 * PROXIMITY RULE: duplication is scored WITHIN a section and never across one. Sections
 * are aisles — nobody reads a label-terms card and a seafood card in the same breath, so
 * a shared construction between them is not repetition anybody can perceive. Scoring it
 * globally produces rewrites that make individual lines worse in exchange for a variety no
 * shopper experiences.
 *
 * @returns {{violations:Array, report:{verbs:Array, emDashShare:number, total:number}}}
 */
export function lintCorpus(cards) {
  const violations = lintOpenerRepetition(cards);
  const list = (cards || []).filter(Boolean);
  const doOf = (c) => String(c?.do ?? c?.do_line ?? '').trim();

  // ── em-dash share ──
  const withEmDash = list.filter((c) => hasEmDashJustification(doOf(c)));
  const share = list.length ? withEmDash.length / list.length : 0;
  if (share > MAX_EMDASH_SHARE) {
    violations.push({
      code: 'EMDASH_SHARE',
      detail:
        `${withEmDash.length}/${list.length} do lines (${Math.round(share * 100)}%) use the ` +
        `em-dash-then-justification shape, over the ${Math.round(MAX_EMDASH_SHARE * 100)}% ceiling`,
    });
  }

  // ── within-section closing duplication ──
  const bySection = new Map();
  for (const c of list) {
    const key = String(c?.section || 'unsectioned');
    if (!bySection.has(key)) bySection.set(key, []);
    bySection.get(key).push(c);
  }
  for (const [section, group] of bySection) {
    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const a = closingConstruction(doOf(group[i]));
        const b = closingConstruction(doOf(group[j]));
        if (!a.length || !b.length) continue;
        const prefix = sharedPrefix(a, b);
        if (isConstruction(prefix)) {
          violations.push({
            code: 'CLOSING_DUPLICATE',
            detail:
              `${section}: ${group[i].slug} and ${group[j].slug} close the same way — ` +
              `"${prefix.join(' ')}…" in both ("${a.join(' ')}" / "${b.join(' ')}")`,
          });
        }
      }
    }
  }

  // ── verb distribution: REPORTED, NEVER FAILED ──
  // Twenty-one lines open with "Read" because twenty-one cards are about reading a label,
  // and that is the physical act. Swapping in synonyms to flatten a histogram makes each
  // line less precise and the corpus no less repetitive. Precision beats variety, so this
  // is a number to look at, not a gate.
  const counts = new Map();
  for (const c of list) {
    const v = firstToken(doOf(c));
    if (v) counts.set(v, (counts.get(v) || 0) + 1);
  }
  const verbs = [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([verb, n]) => ({ verb, n }));

  // ── copula abstraction: REPORTED, NEVER FAILED ──
  // Added 2026-08-02 after the monetization copy pass, where `antithesisChime` PASSED a
  // line that was rejected on sight ("The cart is yours. Keeping it is the membership").
  // It fires on a rhetorical shape rather than a checkable fact, which is weaker footing
  // than anything else here, so it reports. Measured at zero across 961 corpus fields on
  // the day it landed — promote it to a violation only if that holds over time.
  const copula = [];
  for (const c of list) {
    for (const [field, text] of Object.entries({
      headline: c?.headline, do: doOf(c), why: c?.why, tier_note: c?.tier_note,
      detail: c?.detail, kristy_take: c?.kristy_take,
    })) {
      if (!text) continue;
      for (const h of copulaAbstraction(text)) {
        copula.push({ slug: c.slug, field, clause: h.clause, noun: h.noun });
      }
    }
  }

  return {
    violations,
    report: { verbs, emDashShare: share, total: list.length, copulaAbstraction: copula },
  };
}

/* ═══════════════ Readable in the aisle (VOICE_SPEC R2–R4) ═══════════════
   Not wired into lintCard yet (K13); K5–K12 rewrite the cards it fires on.
   Thresholds measured 2026-10-06 over the 109 curated cards: headline+do p95 25 / max 25;
   short_answer p50 62 / max 112; sentence p90 23 / p95 27 / max 43.
   IC-1 (2026-10-14): raised to 28 with the 14-word front. */
export const HEADLINE_DO_MAX = 28; // [PLACEHOLDER] IC-1
export const SHORT_ANSWER_MAX = 40;
export const SENTENCE_MAX = 20;
const READ_FIELDS = ['decision', 'short_answer', 'why', 'look_for', 'watch_out', 'pick_steps', 'science'];
// ponytail: short abbreviation list; extend when a real card splits wrong.
const ABBREV = /\b(e\.g|i\.e|vs|oz|lb|lbs|etc|approx|U\.S)\./gi;
const wordCount = (s) => String(s || '').split(/\s+/).filter(Boolean).length;

/** Split on . ! ? followed by whitespace or end; decimals and ABBREV stay whole. */
export function sentences(text) {
  return String(text || '')
    .replace(ABBREV, (m) => m.replace(/\./g, '\u0000'))
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.replace(/\u0000/g, '.').trim())
    .filter(Boolean);
}

/** Readability findings, same {code, field, detail} shape as voiceTics. Empty is the passing state. */
export function readability(card) {
  const out = [];
  const id = card?.id ?? card?.slug;
  const headline = card?.decision ?? card?.headline;
  const doLine = doLines[id] ?? card?.do ?? card?.do_line;
  const hd = wordCount(headline) + wordCount(doLine);
  if (hd > HEADLINE_DO_MAX) {
    out.push({ code: 'READ_FIVE_SECONDS', field: 'decision', detail: `headline + do line run ${hd} words; the bar is ${HEADLINE_DO_MAX}` });
  }
  const sa = wordCount(card?.short_answer);
  if (sa > SHORT_ANSWER_MAX) {
    out.push({ code: 'READ_FIVE_SECONDS', field: 'short_answer', detail: `${sa} words; the bar is ${SHORT_ANSWER_MAX}` });
  }
  for (const field of READ_FIELDS) {
    const v = field === 'look_for' ? (card?.look_for ?? card?.buying_tips)
      : field === 'decision' ? (card?.decision ?? card?.headline)
      : card?.[field];
    if (v == null) continue;
    for (const raw of [].concat(v)) {
      // look_for entries project labels_decoded as "Term — meaning": that one leading
      // separator is not an aside. Drop the term; a second em-dash still fires.
      const text = field === 'look_for' && typeof raw === 'string' ? raw.replace(/^[^—]*? — /, '') : raw;
      for (const s of sentences(text)) {
        const n = wordCount(s);
        if (n > SENTENCE_MAX) {
          out.push({ code: 'READ_SENTENCE_LONG', field, detail: `${n} words; the bar is ${SENTENCE_MAX}: "${s}"` });
        }
        const stacked = (s.match(/;/g) || []).length + (s.match(/\(/g) || []).length;
        if (s.includes('—')) out.push({ code: 'READ_STACKED', field, detail: `em-dash aside: "${s}"` });
        else if (stacked > 1) out.push({ code: 'READ_STACKED', field, detail: `${stacked} semicolons/parentheticals in one sentence: "${s}"` });
      }
    }
  }
  return out;
}

/* ═══════════════ KTIGHT: pick_steps + science ═══════════════
   The shelf-readable pick (1-3 steps) and one paragraph of why. Not wired into lintCard:
   presence is the ratchet ledger's job (test/ktight.test.js), so a card with neither field
   passes here. */
export const MAX_STEP_WORDS = MAX_DO_WORDS;
export const MAX_SCIENCE_WORDS = 70;
const REDIRECT = [
  /\b(spend|save|put)\b[^.]{0,40}\b(money|budget)\b/i,
  /\b(money|budget)\b[^.]{0,30}\b(elsewhere|instead|toward|towards)\b/i,
];

/** Lint the KTIGHT fields of one question entry. Empty is the passing state. */
export function lintPickSteps(entry) {
  const out = [];
  const e = entry || {};
  const hasSteps = 'pick_steps' in e;
  const hasScience = 'science' in e;
  if (!hasSteps && !hasScience) return out;
  const fail = (code, detail) => out.push({ code, detail });
  const texts = [];

  if (hasSteps) {
    const steps = e.pick_steps;
    if (!Array.isArray(steps) || steps.length < 1 || steps.length > 3 || steps.some((s) => typeof s !== 'string')) {
      fail('STEPS_SHAPE', 'pick_steps is a string[] of 1-3 lines');
    } else {
      const doLine = normText(doLines[e.id]);
      for (const step of steps) {
        if (!step.trim()) { fail('STEPS_EMPTY', 'a blank step'); continue; }
        texts.push(step);
        if (words(step) > MAX_STEP_WORDS) fail('STEPS_TOO_LONG', `${words(step)}w > ${MAX_STEP_WORDS}: "${step}"`);
        if (!/\.$/.test(step.trim()) || step.includes('?')) fail('STEPS_NOT_CLOSED', `a step ends in "." and never asks: "${step}"`);
        if (doLine && normText(step) === doLine) fail('STEPS_COPIES_DO', `a step may extend the do line, never copy it: "${step}"`);
      }
    }
  }

  if (hasScience) {
    const sci = e.science;
    if (typeof sci !== 'string' || !sci.trim()) {
      fail('SCIENCE_SHAPE', 'science is one non-empty string');
    } else {
      texts.push(sci);
      if (/\n/.test(sci) || /^\s*([-•*]|\d+[.)])\s/.test(sci)) fail('SCIENCE_NOT_PARAGRAPH', 'science is one paragraph, no newline or list marker');
      if (words(sci) > MAX_SCIENCE_WORDS) fail('SCIENCE_TOO_LONG', `${words(sci)}w > ${MAX_SCIENCE_WORDS}`);
    }
  }

  const { pick_steps: _s, science: _c, ...rest } = e;
  const known = new Set(JSON.stringify(rest).match(/\d+/g) || []);
  for (const t of texts) {
    if (hasFirstPerson(t)) fail('KT_FIRST_PERSON', `no I/me/my/we/our: "${t}"`);
    if (t.includes('—')) fail('KT_EM_DASH', `no em-dash asides: "${t}"`);
    for (const n of t.match(/\d+/g) || []) {
      if (!known.has(n)) fail('KT_NEW_NUMBER', `"${n}" appears nowhere else in the entry: "${t}"`);
    }
    if (REDIRECT.some((re) => re.test(t))) fail('KT_REDIRECT', `no money redirect: "${t}"`);
    for (const b of britishSpellings(t)) fail('COPY_BRITISH', `American spelling: "${b}"`);
    if (STRAIGHT_QUOTE.test(t)) fail('COPY_STRAIGHT_QUOTE', `typographic quotes only: "${t}"`);
  }
  const steps = Array.isArray(e.pick_steps) ? e.pick_steps.filter((s) => typeof s === 'string') : [];
  const science = typeof e.science === 'string' ? e.science : '';
  // Allowlisted sentences still run the lock; only their CLAIM_TREATMENT finding is dropped.
  const allowed = (s) => PRESERVATION_CURE_SENTENCES.has(s);
  const unlisted = (t) => sentences(t).filter((s) => !allowed(s)).join(' ');
  const exempt = [...steps, science].flatMap(sentences).filter(allowed);
  const hits = [
    ...claimLockViolations({ look_for: steps.map(unlisted), detail: unlisted(science) }),
    ...claimLockViolations({ look_for: exempt, detail: '' }).filter((v) => v.code !== 'CLAIM_TREATMENT'),
  ];
  for (const v of hits) fail(`KT_${v.code}`, v.detail);
  return out;
}

// INVARIANT: each sentence reviewed as preservation sense; adding one is a reviewed corpus change, never a regex.
// Exact pick_steps/science sentences (as split by sentences()) whose meat-cure wording trips the claim lock's
// treatment rule. Any other sentence, including a near-miss of one of these, reads the raw lock. Fail-closed.
export const PRESERVATION_CURE_SENTENCES = Object.freeze(new Set([
  "Read the ingredients list; every curing substance has to be named there.",
  "‘Uncured’ meat is cured, using celery powder instead of added nitrite.",
  "Celery powder is a concentrated natural nitrate source, so it is a curing agent, not the absence of one.",
  "Read each curing ingredient, including salt, sugar and curing agents.",
  "Compare the disclosed curing ingredients across the bacon packs on the shelf.",
  "Bacon labeled uncured can use celery powder as a natural curing source.",
  "US curing-label policy requires curing-mixture ingredients to be listed individually.",
  "The curing ingredients describe the process.",
  "The source set does not establish a health advantage from choosing celery-based curing.",
  "“Uncured” can still mean celery-based curing; read the qualifier.",
  "Ham is the cured leg of pork, and its product name tells how much water the curing added.",
  "Read each curing ingredient in the ingredients statement.",
  "Under US labeling, “bacon” alone means cured pork belly.",
  "Turkey bacon is still a cured product.",
  "Each substance in a curing mixture, such as salt, sugar, or sodium nitrite, must be listed.",
  "Each of these is pork cured with salt and curing agents.",
  "Prosciutto is dry-cured raw ham, not smoked; its low water content lets it be eaten raw.",
  "Salami is a fermented, dried and cured ground product.",
  "Pancetta is cured belly, and cheek meat must carry its true name, such as pork jowl.",
]));

/* ═══════════════════════════ Health first (chf-1) ═══════════════════════════ */

// EVERY CARD AIMS AT THE CLOSEST-TO-NATURE VERSION, NOT THE COOK (Devon 2026-10-12). "80/20
// for burgers" picks for the pan; the card picks for the body. And a health fact shared by a
// family lives on ONE owner card; siblings carry a pointer step `<Read>: see <Owner title>.`
// Plan: docs/plans/card-health-first-plan.md ("One fact, one owner", Piece 1). Not wired into
// `lintCard`; the corpus test holds curated cards to it, with the cards that fail today
// listed below until later pieces empty the list.
export const HEALTH_FIRST_PENDING = new Set([]);

// Word-bounded, so `tender` never matches `tenderized` (a safety fact, not a cook's aim).
export const CULINARY_LEXICON =
  /\b(for burgers?|braise|braising|sear|searing|grill|grilling|bake|baking|roast|roasting|stew|stewing|recipe|crispy|chew|chewy|tender|tenderness|flavou?r|taste|melt|melts|melting|juicy)\b/i;
// Food safety is not cooking advice: a sentence naming a temperature or a spoilage sign stands.
// Bare `crisp` is a produce freshness sign, and ingredient/label names (baking soda, natural flavors) are not an aim.
export const CULINARY_SAFETY_ALLOW =
  /°F|internal temperature|spoil|slime|off smell|sour smell|use-by|sell-by|use by|sell by|baking (soda|powder)|(natural|artificial) flavou?rs?|flavou?r claim/i;

const sentencesOf = (s) => String(s || '').split(/(?<=[.!?])\s+/).filter((x) => x.trim());

export function lintCulinaryAim(entry) {
  const out = [];
  const scan = (field, text) => {
    for (const s of sentencesOf(text)) {
      if (CULINARY_LEXICON.test(s) && !CULINARY_SAFETY_ALLOW.test(s)) out.push({ code: 'CULINARY_AIM', field, text: s });
    }
  };
  if (typeof entry?.decision === 'string') scan('decision', entry.decision);
  if (typeof entry?.cart_pick === 'string') scan('cart_pick', entry.cart_pick);
  for (const step of Array.isArray(entry?.pick_steps) ? entry.pick_steps : []) {
    if (typeof step === 'string') scan('pick_steps', step);
  }
  return out;
}

const KB_TITLE = new Map(perimeterKb.entries.map((e) => [e.id, e.title]));

const ownedFact = (fact, owner, family, pattern) => ({
  fact, owner, ownerTitle: KB_TITLE.get(owner), family, pattern,
});

export const OWNED_FACTS = [
  ownedFact('beef_raising', 'beef_grassfed_vs_grainfed',
    ['ground_beef_lean_ratio', 'beef_cuts_basics',
      'butcher_counter_asking', 'judging_meat_at_the_case', 'organ_meats', 'pick_soup_bones'],
    /grass[- ]?(fed|finished)|grain[- ]?(fed|finished)/i),
  ownedFact('ruminant_grass_term', 'label_grass_fed_term',
    ['lamb_goat', 'bison', 'venison_game', 'goat_sheep_dairy'], /grass[- ]?(fed|finished)/i),
  ownedFact('solution_added', 'pork_cuts_and_enhanced',
    ['ground_beef_lean_ratio', 'beef_cuts_basics', 'butcher_counter_asking',
      'judging_meat_at_the_case', 'lamb_goat', 'bison', 'venison_game'], /solution|enhanced/i),
  ownedFact('mech_tenderized', 'beef_cuts_basics',
    ['ground_beef_lean_ratio', 'butcher_counter_asking', 'judging_meat_at_the_case'],
    /mechanically tenderi[sz]ed|blade[- ]tenderi[sz]ed/i),
  ownedFact('bird_pig_raising', 'label_pasture_raised_feed',
    ['chicken_cuts_basics', 'pork_cuts_and_enhanced'], /pasture[- ]raised|free[- ]range/i),
  ownedFact('chill_water', 'chicken_cuts_basics',
    ['chicken_breast'], /air[- ]chill|water[- ]chill|retained water/i),
  ownedFact('wild_farmed', 'salmon_wild_vs_farmed',
    ['shrimp_imported_vs_domestic', 'white_fish', 'canned_fish_choosing'], /wild[- ]caught|farm[- ]raised|\bfarmed\b/i),
  ownedFact('phosphate_soak', 'scallops', ['shrimp_imported_vs_domestic', 'white_fish'], /phosphate|STPP|soaked/i),
  ownedFact('milk_processing', 'whole_vs_reduced_fat_milk',
    ['plain_kefir', 'cream_cheese', 'goat_sheep_dairy', 'grassfed_butter', 'ghee'], /ultra[- ]pasteuri[sz]ed|homogeni[sz]ed/i),
  ownedFact('oil_extraction', 'label_cold_pressed_expeller', ['cooking_oils'], /cold[- ]pressed|expeller|hexane|solvent/i),
  ownedFact('olive_grade', 'olive_oil_grades', ['cooking_oils'], /extra[- ]virgin/i),
  ownedFact('animal_fat', 'lard_tallow', ['cooking_oils'], /\b(lard|tallow)\b/i),
  ownedFact('dough_conditioners', 'sandwich_bread', ['bagels', 'pretzels', 'flour_basics', 'buns_rolls'], /dough conditioner/i),
  ownedFact('live_ferment', 'sauerkraut', ['kimchi', 'miso', 'fermented_pickles', 'olives'],
    /unpasteuri[sz]ed|live (and active )?cultures/i),
];

export const POINTER = /^[A-Z][^:]{0,40}: see (.+)\.$/;

// The front states the card's own buying ladder; a family card's front may name the owned
// standard (e.g. "100% grass-fed and grass-finished."), the depth may not.
export const REPEATED_CLAIM_FIELDS = [
  'why', 'short_answer', 'detail', 'science', 'kristy_take', 'tier_note',
  'pick_steps', 'buying_tips', 'look_for', 'watch_out', 'labels_decoded',
];

// Every string under a value, in order: prose fields hold strings, arrays and objects.
export function stringsIn(v, out = []) {
  if (typeof v === 'string') out.push(v);
  else if (Array.isArray(v)) v.forEach((x) => stringsIn(x, out));
  else if (v && typeof v === 'object') Object.values(v).forEach((x) => stringsIn(x, out));
  return out;
}

export function lintRepeatedClaim(entry) {
  const out = [];
  for (const row of OWNED_FACTS) {
    if (!row.family.includes(entry?.id)) continue;
    for (const field of REPEATED_CLAIM_FIELDS) {
      if (entry[field] == null) continue;
      // A labels_decoded `term` is the label's own printed word (like an alias); its meaning is still scanned.
      const value = field === 'labels_decoded' && Array.isArray(entry[field])
        ? entry[field].map((i) => (i && typeof i === 'object' ? { ...i, term: undefined } : i))
        : entry[field];
      for (const text of stringsIn(value)) {
        // L4 requires the section's canonical gloss on a family card, so the gloss itself is not a repeat.
        const unglossed = CANONICAL_GLOSSES.reduce((t, g) => t.split(g.gloss).join(''), text);
        if (!POINTER.test(text) && row.pattern.test(unglossed)) out.push({ code: 'REPEATED_CLAIM', fact: row.fact, field, text });
      }
    }
  }
  const titles = new Set(OWNED_FACTS.map((r) => r.ownerTitle));
  for (const text of stringsIn(entry?.pick_steps)) {
    const m = text.match(POINTER);
    if (m && !titles.has(m[1])) out.push({ code: 'POINTER_UNKNOWN_OWNER', field: 'pick_steps', text });
  }
  return out;
}

